mapper.select:
SELECT b.state, b.bill_type, a.id, a.notice_id, a.mat_code, a.mat_name, a.mat_unit, a.mat_spec, a.mat_group, a.mat_group_name, a.notice_out_num, a.out_num, a.not_out_num, a.warehouse_code, a.warehouse_name, a.mat_produce_date, a.mat_valid_period, a.mat_valid_end_date, a.workshop, a.document_id, a.document_table, a.expansion, a.tenant_id, a.create_by, a.create_time, a.update_by, a.update_time, a.factory_code FROM wms_out_notice_detail a LEFT JOIN wms_out_notice b on a.notice_id = b.id where a.del_flag = '0'
and b.bill_type = #{params.billType}
and b.bill_type in
#{item}
and b.state = #{params.state}
and a.warehouse_code = #{params.warehouseCode}
and a.notice_id like concat('%', #{params.noticeId}, '%')
and a.mat_code like concat('%', #{params.matCode}, '%')
and a.create_by like concat('%', #{params.createBy}, '%')
and a.create_time between #{params.createTime[0]} and #{params.createTime[1]}
and a.id in
#{item}
ORDER BY state asc, create_time DESC
